// Every route, with every dependency failing: the exception must reach the log, never the response.
const SECRET = 'SQLITE_CANTOPEN: unable to open /var/lib/booking/db.sqlite';
const boom = async () => { throw new Error(SECRET); };
const allFailing = {
  rooms: { all: boom, find: boom, update: boom },
  bookings: { forRoom: boom, create: boom, cancel: boom },
  invoices: { find: boom },
  mailer: { sendReminders: boom },
  users: { find: boom },
  db: { ping: boom },
};
const requests = {
  'rooms-list': {},
  'rooms-get': { params: { id: 'r1' } },
  'rooms-update': { params: { id: 'r1' }, body: { name: 'Oak' } },
  'bookings-list': { params: { id: 'r1' } },
  'bookings-create': { body: { roomId: 'r1', date: '2026-12-01' } },
  'bookings-cancel': { params: { id: 'b1' } },
  'invoices-get': { params: { id: 'i1' } },
  'reminders-send': { query: { date: '2026-12-01' } },
  'users-me': { user: { id: 'u1' } },
  health: {},
};

test('the failure test covers every route', () => {
  assert.deepEqual(Object.keys(requests).sort(), Object.keys(routes).sort());
});

for (const [name, req] of Object.entries(requests)) {
  test(`${name} does not put the exception in the response, and logs it`, async () => {
    const before = logged.length;
    const r = await dispatch(name, req, allFailing);
    if (name === 'reminders-send') {
      assert.deepEqual(r, { status: 502, body: { message: 'could not send the reminders' } });
    } else {
      assert.deepEqual(r, { status: 500, body: { error: 'internal error' } });
    }
    const text = JSON.stringify(r.body);
    for (const leak of ['SQLITE', '/var/lib', 'Error', 'at ']) assert.ok(!text.includes(leak), `leaks ${leak}`);
    assert.equal(logged.length, before + 1);
    assert.equal(logged.at(-1).where, name);
    assert.match(logged.at(-1).detail, /SQLITE_CANTOPEN/);
  });

  test(`${name} hides a thrown non-Error too`, async () => {
    const thrower = async () => { throw '/etc/booking/secret.conf: permission denied'; };
    const deps2 = Object.fromEntries(Object.entries(allFailing).map(([k, v]) => [k, Object.fromEntries(Object.keys(v).map((m) => [m, thrower]))]));
    const r = await dispatch(name, req, deps2);
    assert.ok(r.status >= 500);
    assert.ok(!JSON.stringify(r.body).includes('secret.conf'));
  });
}

test('the 400, 401 and 404 answers are unchanged', async () => {
  assert.deepEqual(await dispatch('rooms-get', { params: { id: 'zz' } }, deps), { status: 404, body: { error: 'room not found' } });
  assert.deepEqual(await dispatch('invoices-get', { params: { id: 'zz' } }, { ...deps, invoices: { find: async () => null } }), { status: 404, body: { error: 'invoice not found' } });
  assert.deepEqual(await dispatch('bookings-create', { body: {} }, deps), { status: 400, body: { error: 'roomId and date are required' } });
  assert.deepEqual(await dispatch('reminders-send', {}, deps), { status: 400, body: { error: 'date is required' } });
  assert.deepEqual(await dispatch('rooms-update', { params: { id: 'r1' }, body: {} }, deps), { status: 400, body: { error: 'name is required' } });
  assert.deepEqual(await dispatch('users-me', {}, deps), { status: 401, body: { error: 'sign in first' } });
  assert.deepEqual(await dispatch('bookings-cancel', { params: { id: 'b1' } }, deps), { status: 204, body: null });
});
